import java.util.*;

class Solution {
    public List<List<Integer>> generateSubsequences(int[] nums) {
        List<List<Integer>> answer = new ArrayList<>();
        answer.add(new ArrayList<>());
        if (nums.length >= 1) {
            answer.add(Arrays.asList(nums[0]));
        }
        if (nums.length == 2) {
            answer.add(Arrays.asList(nums[1]));
            answer.add(Arrays.asList(nums[0], nums[1]));
        }
        return answer;
    }
